begin;
do $$
declare uid uuid:=gen_random_uuid();other_uid uuid:=gen_random_uuid();d uuid;f uuid;r uuid;u jsonb;blocked boolean;owner_time timestamptz;owner_state text;nonce text;jobs jsonb;job jsonb;
begin
 select publish_at,dispatch_state into owner_time,owner_state from public.facebook_releases where id='bd65da86-3753-4626-9c9a-91cce6d172f8';
 insert into auth.users(id,email,created_at) values(uid,uid||'@fb-quota.invalid',now()),(other_uid,other_uid||'@fb-quota.invalid',now());
 perform set_config('request.jwt.claim.sub',uid::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated')::text,true);
 insert into public.social_connections(user_id,provider,account_id,account_name,encrypted_connection)values(uid,'facebook','fixture','Fixture','unused-fixture');
 insert into public.youtube_connections(user_id,channel_id,channel_title,encrypted_tokens)values(uid,'fixture-fb-cross-channel','Fixture','unused-fixture');
 d:=gen_random_uuid();insert into public.campaign_drafts(id,user_id,title,caption,platforms)values(d,uid,'First','Caption',array['facebook']);
 blocked:=false;begin insert into public.facebook_uploads(id,user_id,draft_id,page_id,title)values(gen_random_uuid(),uid,d,'999010','First');exception when raise_exception then blocked:=sqlerrm like '%not enabled%';end;
 if not blocked then raise exception 'Closed Facebook gate bypass';end if;
 update app_private.billing_config set subscriber_launch=true;
 blocked:=false;begin insert into public.facebook_uploads(id,user_id,draft_id,page_id,title)values(gen_random_uuid(),uid,d,'999010','First');exception when raise_exception then blocked:=sqlerrm like '%not enabled%';end;
 if not blocked then raise exception 'Meta approval gate bypass';end if;
 update app_private.facebook_rollout set enabled=true,meta_approved=true;
 f:=gen_random_uuid();r:=gen_random_uuid();
 insert into public.facebook_uploads(id,user_id,draft_id,page_id,title,outcome)values(f,uid,d,'999010','First','{"videoId":"999020"}');
 insert into public.facebook_releases(id,user_id,upload_id,page_id,video_id,mode)values(r,uid,f,'999010','999020','public');
 if not exists(select 1 from public.campaign_submissions where id=r and not quota_exempt and not quota_released) then raise exception 'Facebook reservation missing';end if;
 -- Another platform shares the same allowance, rather than binding a different artist slot.
 d:=gen_random_uuid();insert into public.campaign_drafts(id,user_id,title,caption,platforms)values(d,uid,'Second','Caption',array['youtube']);
 insert into public.youtube_uploads(id,user_id,draft_id,channel_id,mode,expected)values(gen_random_uuid(),uid,d,'fixture-fb-cross-channel','scheduled',jsonb_build_object('publishAt',now()+interval '1 hour'));
 d:=gen_random_uuid();f:=gen_random_uuid();r:=gen_random_uuid();insert into public.campaign_drafts(id,user_id,title,caption,platforms)values(d,uid,'Third','Caption',array['facebook']);
 insert into public.facebook_uploads(id,user_id,draft_id,page_id,title,outcome)values(f,uid,d,'999010','Third','{"videoId":"999021"}');
 perform public.queue_facebook_release(r,f,now()+interval '1 hour',jsonb_build_object('id',r,'uploadId',f,'userId',uid,'pageId','999010','videoId','999021','mode','scheduled','publishAt',now()+interval '1 hour'),'fixture-signature');
 u:=public.promotion_usage(now()+interval '1 hour');
 if (u->>'remaining')::int<>0 or (u->>'used')::int<>3 or (u->>'queued')::int<>3 then raise exception 'Shared Facebook/YouTube counters incorrect: %',u;end if;
 -- Schedule and immediate-release paths cannot spend the same allowance twice.
 d:=gen_random_uuid();f:=gen_random_uuid();insert into public.campaign_drafts(id,user_id,title,caption,platforms)values(d,uid,'Fourth','Caption',array['facebook']);
 blocked:=false;begin insert into public.facebook_uploads(id,user_id,draft_id,page_id,title)values(f,uid,d,'999010','Fourth');exception when raise_exception then blocked:=sqlerrm like '%allowance%';end;
 if not blocked then raise exception 'Upload ignored exhausted allowance';end if;
 blocked:=false;begin perform public.queue_facebook_release(r,(select upload_id from public.facebook_releases where id=r),now()+interval '2 hours',(select outcome from public.facebook_releases where id=r),'fixture-signature');exception when raise_exception then blocked:=sqlerrm like '%already%';end;
 if not blocked then raise exception 'Subscriber duplicate schedule allowed';end if;
 if app_private.facebook_dispatch_allowed(uid,now()+interval '8 days') then raise exception 'Expired trial dispatch allowed';end if;
 update app_private.facebook_rollout set enabled=false;
 if app_private.facebook_dispatch_allowed(uid,now()+interval '1 hour') then raise exception 'Paused rollout dispatch allowed';end if;
 update app_private.facebook_rollout set enabled=true;
 -- Safe job authorization is generated by the DB, never inferred from a customer receipt.
 update public.facebook_releases set publish_at=now()-interval '1 minute' where id=r;
 update public.campaign_submissions set snapshot=jsonb_set(snapshot,'{planned_at}',to_jsonb(now()-interval '1 minute')) where id=r;
 nonce:=encode(extensions.gen_random_bytes(32),'hex');insert into app_private.facebook_dispatch_nonces values(encode(extensions.digest(nonce,'sha256'),'hex'),now()+interval '2 minutes');
 jobs:=public.claim_facebook_dispatch(nonce);
 select value into job from jsonb_array_elements(jobs) where value->'release'->>'id'=r::text;
 if job is null or not (job->>'subscriberAuthorized')::boolean then raise exception 'Reserved subscriber job not authorized';end if;
 if (select publish_at is distinct from owner_time or dispatch_state is distinct from owner_state from public.facebook_releases where id='bd65da86-3753-4626-9c9a-91cce6d172f8') then raise exception 'Owner schedule changed';end if;
 if has_table_privilege('authenticated','app_private.facebook_rollout','UPDATE') or has_table_privilege('authenticated','app_private.direct_destinations','INSERT') or has_column_privilege('authenticated','public.facebook_releases','dispatch_state','UPDATE') then raise exception 'Client rollout or quota privilege leak';end if;
 perform set_config('fb_test.uid',uid::text,true);perform set_config('fb_test.other',other_uid::text,true);perform set_config('fb_test.upload',f::text,true);
end $$;
-- An older customer needs a live active subscription; sandbox and cancelled records do not unlock it.
do $$
declare uid uuid:=gen_random_uuid();d uuid:=gen_random_uuid();f uuid:=gen_random_uuid();r uuid:=gen_random_uuid();blocked boolean;
begin
 insert into auth.users(id,email,created_at)values(uid,uid||'@fb-paid.invalid',now()-interval '30 days');
 perform set_config('request.jwt.claim.sub',uid::text,true);
 insert into public.social_connections(user_id,provider,account_id,account_name,encrypted_connection)values(uid,'facebook','paid-fixture','Paid fixture','unused');
 insert into public.campaign_drafts(id,user_id,title,caption,platforms)values(d,uid,'Paid','Caption',array['facebook']);
 insert into app_private.subscriptions(subscription_id,user_id,customer_id,plan,status,period_end,livemode,event_created)values('sub_fb_fixture',uid,'cus_fb_fixture','starter','active',now()+interval '2 hours',false,1);
 blocked:=false;begin insert into public.facebook_uploads(id,user_id,draft_id,page_id,title)values(f,uid,d,'999012','Paid');exception when raise_exception then blocked:=sqlerrm like '%active subscription%';end;
 if not blocked then raise exception 'Sandbox subscription unlocked real publication';end if;
 update app_private.subscriptions set livemode=true where subscription_id='sub_fb_fixture';
 insert into public.facebook_uploads(id,user_id,draft_id,page_id,title,outcome)values(f,uid,d,'999012','Paid','{"videoId":"999022"}');
 blocked:=false;begin perform public.queue_facebook_release(r,f,now()+interval '3 hours',jsonb_build_object('id',r,'uploadId',f,'userId',uid,'pageId','999012','videoId','999022','mode','scheduled','publishAt',now()+interval '3 hours'),'fixture-signature');exception when raise_exception then blocked:=sqlerrm like '%paid period%';end;
 if not blocked then raise exception 'Schedule beyond subscription accepted';end if;
 if exists(select 1 from public.facebook_releases where id=r) or exists(select 1 from public.campaign_submissions where id=r) then raise exception 'Rejected schedule left partial reservation';end if;
 if not app_private.facebook_dispatch_allowed(uid,now()+interval '1 hour') then raise exception 'Active paid subscriber dispatch denied';end if;
 update app_private.subscriptions set status='canceled' where subscription_id='sub_fb_fixture';
 if app_private.facebook_dispatch_allowed(uid,now()+interval '1 hour') then raise exception 'Cancelled subscription dispatch allowed';end if;
 perform set_config('request.jwt.claim.sub',current_setting('fb_test.uid'),true);
end $$;
-- Exercise actual RLS, not just trigger logic under the postgres role.
set local role authenticated;
do $$
declare n int;blocked boolean:=false;
begin
 if public.facebook_publishing_access()->>'owner'<>'false' then raise exception 'Subscriber gained owner access';end if;
 select count(*) into n from public.facebook_uploads where user_id<>auth.uid();if n<>0 then raise exception 'Cross-account read leak';end if;
 begin update public.facebook_releases set dispatch_state='done' where user_id=auth.uid();exception when insufficient_privilege then blocked:=true;end;
 if not blocked then raise exception 'Client dispatch state write allowed';end if;
 perform set_config('request.jwt.claim.sub',current_setting('fb_test.other'),true);
 select count(*) into n from public.facebook_uploads;if n<>0 then raise exception 'Other account saw prepared videos';end if;
end $$;
reset role;
rollback;
